'use client'
import {useEffect,useState} from 'react'
export default function MoviePage({params}:{params:Promise<{slug:string}>}){const [data,setData]=useState<any>(null);const [slug,setSlug]=useState('');const [msg,setMsg]=useState('');useEffect(()=>{params.then(p=>{setSlug(p.slug);fetch('/api/movies/'+p.slug).then(r=>r.json()).then(setData)})},[params]);if(!data)return <main className="movie"><div>Loading...</div></main>;if(data.error)return <main className="movie"><div>Movie not found.</div></main>;const {movie,summary}=data;const total=summary.total||0;const pct=summary.percent_good;const status=total<100?'UNRATED':pct>=70?'YES':'NO';const cls=total<100?'unrated':status==='YES'?'good':'bad';async function vote(v:'good'|'bad'){setMsg('Saving...');const r=await fetch('/api/movies/'+slug+'/vote',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({vote:v})});setMsg(r.ok?'Thanks for voting!':'Could not save your vote.');if(r.ok)location.reload()}return <main className="movie"><section className={'card '+cls}>{movie.poster_path?<img className="poster" src={'https://image.tmdb.org/t/p/w500'+movie.poster_path} alt={movie.title}/>:<div className="poster"/>}<div className="details"><div className="year">{movie.year}</div><h1>{movie.title}</h1><div className="status">{status}</div><div className="desc">{total<100?'Not enough ratings yet.':`${pct}% of voters say this movie is good.`}</div>{movie.overview&&<p className="desc">{movie.overview}</p>}<div className="votes">{total} ratings</div><div className="voteBtns"><button onClick={()=>vote('good')}>👍 Yes</button><button onClick={()=>vote('bad')}>👎 No</button></div><div className="note">{msg}</div></div></section></main>}
